      Hooks: "\u30D5\u30C3\u30AF",
      "Loading hooks...": "\u30D5\u30C3\u30AF\u3092\u8AAD\u307F\u8FBC\u3093\u3067\u3044\u307E\u3059...",
      "Error loading hooks:": "\u30D5\u30C3\u30AF\u306E\u8AAD\u307F\u8FBC\u307F\u30A8\u30E9\u30FC\uFF1A",
