      "Esc to back": "Esc \u623B\u308B",
      "\u2191\u2193 to navigate \xB7 Enter to select \xB7 Esc to close": "\u2191\u2193 \u30CA\u30D3\u30B2\u30FC\u30C8 \xB7 Enter \u9078\u629E \xB7 Esc \u9589\u3058\u308B",
      "\u2191\u2193 to navigate \xB7 Enter to select \xB7 Esc to back": "\u2191\u2193 \u30CA\u30D3\u30B2\u30FC\u30C8 \xB7 Enter \u9078\u629E \xB7 Esc \u623B\u308B",
      "\u2191\u2193 to navigate \xB7 Enter to confirm \xB7 Esc to back": "\u2191\u2193 \u30CA\u30D3\u30B2\u30FC\u30C8 \xB7 Enter \u78BA\u8A8D \xB7 Esc \u623B\u308B",
      "User Settings (global)": "\u30E6\u30FC\u30B6\u30FC\u8A2D\u5B9A\uFF08\u30B0\u30ED\u30FC\u30D0\u30EB\uFF09",
      "Workspace Settings (project-specific)": "\u30EF\u30FC\u30AF\u30B9\u30DA\u30FC\u30B9\u8A2D\u5B9A\uFF08\u30D7\u30ED\u30B8\u30A7\u30AF\u30C8\u56FA\u6709\uFF09",
      "Disable server:": "\u30B5\u30FC\u30D0\u30FC\u3092\u7121\u52B9\u5316:",
      "Select where to add the server to the exclude list:": "\u30B5\u30FC\u30D0\u30FC\u3092\u9664\u5916\u30EA\u30B9\u30C8\u306B\u8FFD\u52A0\u3059\u308B\u5834\u6240\u3092\u9078\u629E\u3057\u3066\u304F\u3060\u3055\u3044:",
      "Press Enter to confirm, Esc to cancel": "Enter \u3067\u78BA\u8A8D\u3001Esc \u3067\u30AD\u30E3\u30F3\u30BB\u30EB",
