      "Extension MCPs": "\u62E1\u5F35\u6A5F\u80FDMCP",
      server: "\u30B5\u30FC\u30D0\u30FC",
      servers: "\u30B5\u30FC\u30D0\u30FC",
      "Add MCP servers to your settings to get started.": "\u8A2D\u5B9A\u306BMCP\u30B5\u30FC\u30D0\u30FC\u3092\u8FFD\u52A0\u3057\u3066\u958B\u59CB\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
      "Run qwen --debug to see error logs": "qwen --debug \u3092\u5B9F\u884C\u3057\u3066\u30A8\u30E9\u30FC\u30ED\u30B0\u3092\u78BA\u8A8D\u3057\u3066\u304F\u3060\u3055\u3044",
      // MCP OAuth Authentication
      "OAuth Authentication": "OAuth \u8A8D\u8A3C",
      "Press Enter to start authentication, Esc to go back": "Enter \u3067\u8A8D\u8A3C\u958B\u59CB\u3001Esc \u3067\u623B\u308B",
      "Authenticating... Please complete the login in your browser.": "\u8A8D\u8A3C\u4E2D... \u30D6\u30E9\u30A6\u30B6\u3067\u30ED\u30B0\u30A4\u30F3\u3092\u5B8C\u4E86\u3057\u3066\u304F\u3060\u3055\u3044\u3002",
      "Press Enter or Esc to go back": "Enter \u307E\u305F\u306F Esc \u3067\u623B\u308B",
      // MCP Tool List
      "No tools available for this server.": "\u3053\u306E\u30B5\u30FC\u30D0\u30FC\u306B\u306F\u4F7F\u7528\u53EF\u80FD\u306A\u30C4\u30FC\u30EB\u304C\u3042\u308A\u307E\u305B\u3093\u3002",
