      "e.g.,": "\u4F8B\uFF1A",
      or: "\u307E\u305F\u306F",
      "Enter permission rule\u2026": "\u6A29\u9650\u30EB\u30FC\u30EB\u3092\u5165\u529B\u2026",
      "Enter to submit \xB7 Esc to cancel": "Enter \u3067\u9001\u4FE1 \xB7 Esc \u3067\u30AD\u30E3\u30F3\u30BB\u30EB",
      "Where should this rule be saved?": "\u3053\u306E\u30EB\u30FC\u30EB\u3092\u3069\u3053\u306B\u4FDD\u5B58\u3057\u307E\u3059\u304B\uFF1F",
      "Enter to confirm \xB7 Esc to cancel": "Enter \u3067\u78BA\u8A8D \xB7 Esc \u3067\u30AD\u30E3\u30F3\u30BB\u30EB",
