      "Are you sure you want to delete this permission rule?": "\u3053\u306E\u6A29\u9650\u30EB\u30FC\u30EB\u3092\u524A\u9664\u3057\u3066\u3082\u3088\u308D\u3057\u3044\u3067\u3059\u304B\uFF1F",
      "Permissions:": "\u6A29\u9650\uFF1A",
      "(\u2190/\u2192 or tab to cycle)": "\uFF08\u2190/\u2192 \u307E\u305F\u306F Tab \u3067\u5207\u66FF\uFF09",
      "Press \u2191\u2193 to navigate \xB7 Enter to select \xB7 Type to search \xB7 Esc to cancel": "\u2191\u2193 \u3067\u30CA\u30D3\u30B2\u30FC\u30C8 \xB7 Enter \u3067\u9078\u629E \xB7 \u5165\u529B\u3067\u691C\u7D22 \xB7 Esc \u3067\u30AD\u30E3\u30F3\u30BB\u30EB",
      "Search\u2026": "\u691C\u7D22\u2026",
      "Use /trust to manage folder trust settings for this workspace.": "/trust \u3092\u4F7F\u7528\u3057\u3066\u3053\u306E\u30EF\u30FC\u30AF\u30B9\u30DA\u30FC\u30B9\u306E\u30D5\u30A9\u30EB\u30C0\u4FE1\u983C\u8A2D\u5B9A\u3092\u7BA1\u7406\u3057\u307E\u3059\u3002",
      // Workspace directory management
      "Add directory\u2026": "\u30C7\u30A3\u30EC\u30AF\u30C8\u30EA\u3092\u8FFD\u52A0\u2026",
      "Add directory to workspace": "\u30EF\u30FC\u30AF\u30B9\u30DA\u30FC\u30B9\u306B\u30C7\u30A3\u30EC\u30AF\u30C8\u30EA\u3092\u8FFD\u52A0",
      "Qwen Code can read files in the workspace, and make edits when auto-accept edits is on.": "Qwen Code \u306F\u30EF\u30FC\u30AF\u30B9\u30DA\u30FC\u30B9\u5185\u306E\u30D5\u30A1\u30A4\u30EB\u3092\u8AAD\u307F\u53D6\u308A\u3001\u81EA\u52D5\u7DE8\u96C6\u627F\u8A8D\u304C\u6709\u52B9\u306A\u5834\u5408\u306F\u7DE8\u96C6\u3092\u884C\u3048\u307E\u3059\u3002",
      "Qwen Code will be able to read files in this directory and make edits when auto-accept edits is on.": "Qwen Code \u306F\u3053\u306E\u30C7\u30A3\u30EC\u30AF\u30C8\u30EA\u5185\u306E\u30D5\u30A1\u30A4\u30EB\u3092\u8AAD\u307F\u53D6\u308A\u3001\u81EA\u52D5\u7DE8\u96C6\u627F\u8A8D\u304C\u6709\u52B9\u306A\u5834\u5408\u306F\u7DE8\u96C6\u3092\u884C\u3048\u307E\u3059\u3002",
      "Enter the path to the directory:": "\u30C7\u30A3\u30EC\u30AF\u30C8\u30EA\u306E\u30D1\u30B9\u3092\u5165\u529B\u3057\u3066\u304F\u3060\u3055\u3044:",
      "Enter directory path\u2026": "\u30C7\u30A3\u30EC\u30AF\u30C8\u30EA\u30D1\u30B9\u3092\u5165\u529B\u2026",
      "Tab to complete \xB7 Enter to add \xB7 Esc to cancel": "Tab \u3067\u88DC\u5B8C \xB7 Enter \u3067\u8FFD\u52A0 \xB7 Esc \u3067\u30AD\u30E3\u30F3\u30BB\u30EB",
      "Remove directory?": "\u30C7\u30A3\u30EC\u30AF\u30C8\u30EA\u3092\u524A\u9664\u3057\u307E\u3059\u304B\uFF1F",
      "Are you sure you want to remove this directory from the workspace?": "\u3053\u306E\u30C7\u30A3\u30EC\u30AF\u30C8\u30EA\u3092\u30EF\u30FC\u30AF\u30B9\u30DA\u30FC\u30B9\u304B\u3089\u524A\u9664\u3057\u3066\u3082\u3088\u308D\u3057\u3044\u3067\u3059\u304B\uFF1F",
      "  (Original working directory)": "  \uFF08\u5143\u306E\u4F5C\u696D\u30C7\u30A3\u30EC\u30AF\u30C8\u30EA\uFF09",
      "  (from settings)": "  \uFF08\u8A2D\u5B9A\u3088\u308A\uFF09",
      "Directory does not exist.": "\u30C7\u30A3\u30EC\u30AF\u30C8\u30EA\u304C\u5B58\u5728\u3057\u307E\u305B\u3093\u3002",
      "Path is not a directory.": "\u30D1\u30B9\u306F\u30C7\u30A3\u30EC\u30AF\u30C8\u30EA\u3067\u306F\u3042\u308A\u307E\u305B\u3093\u3002",
      "This directory is already in the workspace.": "\u3053\u306E\u30C7\u30A3\u30EC\u30AF\u30C8\u30EA\u306F\u3059\u3067\u306B\u30EF\u30FC\u30AF\u30B9\u30DA\u30FC\u30B9\u306B\u542B\u307E\u308C\u3066\u3044\u307E\u3059\u3002",
      "Already covered by existing directory: {{dir}}": "\u65E2\u5B58\u306E\u30C7\u30A3\u30EC\u30AF\u30C8\u30EA\u306B\u3088\u3063\u3066\u65E2\u306B\u30AB\u30D0\u30FC\u3055\u308C\u3066\u3044\u307E\u3059: {{dir}}",
