      Reason: "\u539F\u56E0",
      "Tools must have both name and description to be used by the LLM.": "\u5DE5\u5177\u5FC5\u987B\u540C\u65F6\u5177\u6709\u540D\u79F0\u548C\u63CF\u8FF0\u624D\u80FD\u88AB LLM \u4F7F\u7528\u3002",
      // ============================================================================
      // Commands - Chat
      // ============================================================================
      "Manage conversation history.": "\u7BA1\u7406\u5BF9\u8BDD\u5386\u53F2",
      "List saved conversation checkpoints": "\u5217\u51FA\u5DF2\u4FDD\u5B58\u7684\u5BF9\u8BDD\u68C0\u67E5\u70B9",
      "No saved conversation checkpoints found.": "\u672A\u627E\u5230\u5DF2\u4FDD\u5B58\u7684\u5BF9\u8BDD\u68C0\u67E5\u70B9",
      "List of saved conversations:": "\u5DF2\u4FDD\u5B58\u7684\u5BF9\u8BDD\u5217\u8868\uFF1A",
      "Note: Newest last, oldest first": "\u6CE8\u610F\uFF1A\u6700\u65B0\u7684\u5728\u6700\u540E\uFF0C\u6700\u65E7\u7684\u5728\u6700\u524D",
      "Save the current conversation as a checkpoint. Usage: /chat save <tag>": "\u5C06\u5F53\u524D\u5BF9\u8BDD\u4FDD\u5B58\u4E3A\u68C0\u67E5\u70B9\u3002\u7528\u6CD5\uFF1A/chat save <tag>",
      "Missing tag. Usage: /chat save <tag>": "\u7F3A\u5C11\u6807\u7B7E\u3002\u7528\u6CD5\uFF1A/chat save <tag>",
      "Delete a conversation checkpoint. Usage: /chat delete <tag>": "\u5220\u9664\u5BF9\u8BDD\u68C0\u67E5\u70B9\u3002\u7528\u6CD5\uFF1A/chat delete <tag>",
      "Missing tag. Usage: /chat delete <tag>": "\u7F3A\u5C11\u6807\u7B7E\u3002\u7528\u6CD5\uFF1A/chat delete <tag>",
      "Conversation checkpoint '{{tag}}' has been deleted.": "\u5BF9\u8BDD\u68C0\u67E5\u70B9 '{{tag}}' \u5DF2\u5220\u9664",
      "Error: No checkpoint found with tag '{{tag}}'.": "\u9519\u8BEF\uFF1A\u672A\u627E\u5230\u6807\u7B7E\u4E3A '{{tag}}' \u7684\u68C0\u67E5\u70B9",
      "Resume a conversation from a checkpoint. Usage: /chat resume <tag>": "\u4ECE\u68C0\u67E5\u70B9\u6062\u590D\u5BF9\u8BDD\u3002\u7528\u6CD5\uFF1A/chat resume <tag>",
      "Missing tag. Usage: /chat resume <tag>": "\u7F3A\u5C11\u6807\u7B7E\u3002\u7528\u6CD5\uFF1A/chat resume <tag>",
      "No saved checkpoint found with tag: {{tag}}.": "\u672A\u627E\u5230\u6807\u7B7E\u4E3A {{tag}} \u7684\u5DF2\u4FDD\u5B58\u68C0\u67E5\u70B9",
      "A checkpoint with the tag {{tag}} already exists. Do you want to overwrite it?": "\u6807\u7B7E\u4E3A {{tag}} \u7684\u68C0\u67E5\u70B9\u5DF2\u5B58\u5728\u3002\u60A8\u8981\u8986\u76D6\u5B83\u5417\uFF1F",
      "No chat client available to save conversation.": "\u6CA1\u6709\u53EF\u7528\u7684\u804A\u5929\u5BA2\u6237\u7AEF\u6765\u4FDD\u5B58\u5BF9\u8BDD",
      "Conversation checkpoint saved with tag: {{tag}}.": "\u5BF9\u8BDD\u68C0\u67E5\u70B9\u5DF2\u4FDD\u5B58\uFF0C\u6807\u7B7E\uFF1A{{tag}}",
      "No conversation found to save.": "\u672A\u627E\u5230\u8981\u4FDD\u5B58\u7684\u5BF9\u8BDD",
      "No chat client available to share conversation.": "\u6CA1\u6709\u53EF\u7528\u7684\u804A\u5929\u5BA2\u6237\u7AEF\u6765\u5206\u4EAB\u5BF9\u8BDD",
      "Invalid file format. Only .md and .json are supported.": "\u65E0\u6548\u7684\u6587\u4EF6\u683C\u5F0F\u3002\u4EC5\u652F\u6301 .md \u548C .json \u6587\u4EF6",
      "Error sharing conversation: {{error}}": "\u5206\u4EAB\u5BF9\u8BDD\u65F6\u51FA\u9519\uFF1A{{error}}",
      "Conversation shared to {{filePath}}": "\u5BF9\u8BDD\u5DF2\u5206\u4EAB\u5230 {{filePath}}",
      "No conversation found to share.": "\u672A\u627E\u5230\u8981\u5206\u4EAB\u7684\u5BF9\u8BDD",
      "Share the current conversation to a markdown or json file. Usage: /chat share <file>": "\u5C06\u5F53\u524D\u5BF9\u8BDD\u5206\u4EAB\u5230 markdown \u6216 json \u6587\u4EF6\u3002\u7528\u6CD5\uFF1A/chat share <file>",
      // ============================================================================
      // Commands - Summary
      // ============================================================================
      "Generate a project summary and save it to .qwen/PROJECT_SUMMARY.md": "\u751F\u6210\u9879\u76EE\u6458\u8981\u5E76\u4FDD\u5B58\u5230 .qwen/PROJECT_SUMMARY.md",
      "No chat client available to generate summary.": "\u6CA1\u6709\u53EF\u7528\u7684\u804A\u5929\u5BA2\u6237\u7AEF\u6765\u751F\u6210\u6458\u8981",
      "Already generating summary, wait for previous request to complete": "\u6B63\u5728\u751F\u6210\u6458\u8981\uFF0C\u8BF7\u7B49\u5F85\u4E0A\u4E00\u4E2A\u8BF7\u6C42\u5B8C\u6210",
      "No conversation found to summarize.": "\u672A\u627E\u5230\u8981\u603B\u7ED3\u7684\u5BF9\u8BDD",
      "Failed to generate project context summary: {{error}}": "\u751F\u6210\u9879\u76EE\u4E0A\u4E0B\u6587\u6458\u8981\u5931\u8D25\uFF1A{{error}}",
      "Saved project summary to {{filePathForDisplay}}.": "\u9879\u76EE\u6458\u8981\u5DF2\u4FDD\u5B58\u5230 {{filePathForDisplay}}",
      "Saving project summary...": "\u6B63\u5728\u4FDD\u5B58\u9879\u76EE\u6458\u8981...",
      "Generating project summary...": "\u6B63\u5728\u751F\u6210\u9879\u76EE\u6458\u8981...",
      "Failed to generate summary - no text content received from LLM response": "\u751F\u6210\u6458\u8981\u5931\u8D25 - \u672A\u4ECE LLM \u54CD\u5E94\u4E2D\u63A5\u6536\u5230\u6587\u672C\u5185\u5BB9",
