      "Content generator configuration not available.": "\u5185\u5BB9\u751F\u6210\u5668\u914D\u7F6E\u4E0D\u53EF\u7528",
      "Authentication type not available.": "\u8BA4\u8BC1\u7C7B\u578B\u4E0D\u53EF\u7528",
      "No models available for the current authentication type ({{authType}}).": "\u5F53\u524D\u8BA4\u8BC1\u7C7B\u578B ({{authType}}) \u6CA1\u6709\u53EF\u7528\u7684\u6A21\u578B",
      // ============================================================================
      // Commands - Clear
      // ============================================================================
      "Starting a new session, resetting chat, and clearing terminal.": "\u6B63\u5728\u5F00\u59CB\u65B0\u4F1A\u8BDD\uFF0C\u91CD\u7F6E\u804A\u5929\u5E76\u6E05\u5C4F\u3002",
      "Starting a new session and clearing.": "\u6B63\u5728\u5F00\u59CB\u65B0\u4F1A\u8BDD\u5E76\u6E05\u5C4F\u3002",
      // ============================================================================
      // Commands - Compress
      // ============================================================================
      "Already compressing, wait for previous request to complete": "\u6B63\u5728\u538B\u7F29\u4E2D\uFF0C\u8BF7\u7B49\u5F85\u4E0A\u4E00\u4E2A\u8BF7\u6C42\u5B8C\u6210",
      "Failed to compress chat history.": "\u538B\u7F29\u804A\u5929\u5386\u53F2\u5931\u8D25",
      "Failed to compress chat history: {{error}}": "\u538B\u7F29\u804A\u5929\u5386\u53F2\u5931\u8D25\uFF1A{{error}}",
      "Compressing chat history": "\u6B63\u5728\u538B\u7F29\u804A\u5929\u5386\u53F2",
      "Chat history compressed from {{originalTokens}} to {{newTokens}} tokens.": "\u804A\u5929\u5386\u53F2\u5DF2\u4ECE {{originalTokens}} \u4E2A token \u538B\u7F29\u5230 {{newTokens}} \u4E2A token\u3002",
      "Compression was not beneficial for this history size.": "\u5BF9\u4E8E\u6B64\u5386\u53F2\u8BB0\u5F55\u5927\u5C0F\uFF0C\u538B\u7F29\u6CA1\u6709\u76CA\u5904\u3002",
      "Chat history compression did not reduce size. This may indicate issues with the compression prompt.": "\u804A\u5929\u5386\u53F2\u538B\u7F29\u672A\u80FD\u51CF\u5C0F\u5927\u5C0F\u3002\u8FD9\u53EF\u80FD\u8868\u660E\u538B\u7F29\u63D0\u793A\u5B58\u5728\u95EE\u9898\u3002",
      "Could not compress chat history due to a token counting error.": "\u7531\u4E8E token \u8BA1\u6570\u9519\u8BEF\uFF0C\u65E0\u6CD5\u538B\u7F29\u804A\u5929\u5386\u53F2\u3002",
      "Chat history is already compressed.": "\u804A\u5929\u5386\u53F2\u5DF2\u7ECF\u538B\u7F29\u3002",
      // ============================================================================
      // Commands - Directory
      // ============================================================================
      "Configuration is not available.": "\u914D\u7F6E\u4E0D\u53EF\u7528\u3002",
      "Please provide at least one path to add.": "\u8BF7\u63D0\u4F9B\u81F3\u5C11\u4E00\u4E2A\u8981\u6DFB\u52A0\u7684\u8DEF\u5F84\u3002",
      "The /directory add command is not supported in restrictive sandbox profiles. Please use --include-directories when starting the session instead.": "/directory add \u547D\u4EE4\u5728\u9650\u5236\u6027\u6C99\u7BB1\u914D\u7F6E\u6587\u4EF6\u4E2D\u4E0D\u53D7\u652F\u6301\u3002\u8BF7\u6539\u4E3A\u5728\u542F\u52A8\u4F1A\u8BDD\u65F6\u4F7F\u7528 --include-directories\u3002",
      "Error adding '{{path}}': {{error}}": "\u6DFB\u52A0 '{{path}}' \u65F6\u51FA\u9519\uFF1A{{error}}",
      "Successfully added QWEN.md files from the following directories if there are:\n- {{directories}}": "\u5982\u679C\u5B58\u5728\uFF0C\u5DF2\u6210\u529F\u4ECE\u4EE5\u4E0B\u76EE\u5F55\u6DFB\u52A0 QWEN.md \u6587\u4EF6\uFF1A\n- {{directories}}",
      "Error refreshing memory: {{error}}": "\u5237\u65B0\u5185\u5B58\u65F6\u51FA\u9519\uFF1A{{error}}",
      "Successfully added directories:\n- {{directories}}": "\u6210\u529F\u6DFB\u52A0\u76EE\u5F55\uFF1A\n- {{directories}}",
      "Current workspace directories:\n{{directories}}": "\u5F53\u524D\u5DE5\u4F5C\u533A\u76EE\u5F55\uFF1A\n{{directories}}",
      // ============================================================================
      // Commands - Docs
      // ============================================================================
      "Please open the following URL in your browser to view the documentation:\n{{url}}": "\u8BF7\u5728\u6D4F\u89C8\u5668\u4E2D\u6253\u5F00\u4EE5\u4E0B URL \u4EE5\u67E5\u770B\u6587\u6863\uFF1A\n{{url}}",
      "Opening documentation in your browser: {{url}}": "\u6B63\u5728\u6D4F\u89C8\u5668\u4E2D\u6253\u5F00\u6587\u6863\uFF1A{{url}}",
