      'Yes, always allow tool "{{tool}}" from server "{{server}}"': '\u662F\uFF0C\u603B\u662F\u5141\u8BB8\u6765\u81EA\u670D\u52A1\u5668 "{{server}}" \u7684\u5DE5\u5177 "{{tool}}"',
      'Yes, always allow all tools from server "{{server}}"': '\u662F\uFF0C\u603B\u662F\u5141\u8BB8\u6765\u81EA\u670D\u52A1\u5668 "{{server}}" \u7684\u6240\u6709\u5DE5\u5177',
