      ", {{inProgress}} in progress": "\uFF0C{{inProgress}} \u4E2A\u8FDB\u884C\u4E2D",
      "Pending Tasks:": "\u5F85\u5904\u7406\u4EFB\u52A1\uFF1A",
      "What would you like to do?": "\u60A8\u60F3\u8981\u505A\u4EC0\u4E48\uFF1F",
      "Choose how to proceed with your session:": "\u9009\u62E9\u5982\u4F55\u7EE7\u7EED\u60A8\u7684\u4F1A\u8BDD\uFF1A",
