      "Search\u2026": "\u641C\u7D22\u2026",
      "Use /trust to manage folder trust settings for this workspace.": "\u4F7F\u7528 /trust \u7BA1\u7406\u6B64\u5DE5\u4F5C\u533A\u7684\u6587\u4EF6\u5939\u4FE1\u4EFB\u8BBE\u7F6E\u3002",
      // Workspace directory management
      "Add directory\u2026": "\u6DFB\u52A0\u76EE\u5F55\u2026",
