      "{{count}} {{name}} files": "{{count}} \u4E2A {{name}} \u6587\u4EF6",
      "{{count}} MCP server": "{{count}} \u4E2A MCP \u670D\u52A1\u5668",
      "{{count}} MCP servers": "{{count}} \u4E2A MCP \u670D\u52A1\u5668",
      "{{count}} Blocked": "{{count}} \u4E2A\u5DF2\u963B\u6B62",
      "(ctrl+t to view)": "\uFF08\u6309 ctrl+t \u67E5\u770B\uFF09",
      "(ctrl+t to toggle)": "\uFF08\u6309 ctrl+t \u5207\u6362\uFF09",
      "Press Ctrl+C again to exit.": "\u518D\u6B21\u6309 Ctrl+C \u9000\u51FA",
      "Press Ctrl+D again to exit.": "\u518D\u6B21\u6309 Ctrl+D \u9000\u51FA",
      "Press Esc again to clear.": "\u518D\u6B21\u6309 Esc \u6E05\u9664",
      // ============================================================================
      // MCP Status
      // ============================================================================
      "No MCP servers configured.": "\u672A\u914D\u7F6E MCP \u670D\u52A1\u5668",
      "\u23F3 MCP servers are starting up ({{count}} initializing)...": "\u23F3 MCP \u670D\u52A1\u5668\u6B63\u5728\u542F\u52A8\uFF08{{count}} \u4E2A\u6B63\u5728\u521D\u59CB\u5316\uFF09...",
      "Note: First startup may take longer. Tool availability will update automatically.": "\u6CE8\u610F\uFF1A\u9996\u6B21\u542F\u52A8\u53EF\u80FD\u9700\u8981\u66F4\u957F\u65F6\u95F4\u3002\u5DE5\u5177\u53EF\u7528\u6027\u5C06\u81EA\u52A8\u66F4\u65B0",
      "Configured MCP servers:": "\u5DF2\u914D\u7F6E\u7684 MCP \u670D\u52A1\u5668\uFF1A",
      Ready: "\u5C31\u7EEA",
      "Starting... (first startup may take longer)": "\u6B63\u5728\u542F\u52A8...\uFF08\u9996\u6B21\u542F\u52A8\u53EF\u80FD\u9700\u8981\u66F4\u957F\u65F6\u95F4\uFF09",
      Disconnected: "\u5DF2\u65AD\u5F00\u8FDE\u63A5",
      "{{count}} tool": "{{count}} \u4E2A\u5DE5\u5177",
      "{{count}} tools": "{{count}} \u4E2A\u5DE5\u5177",
      "{{count}} prompt": "{{count}} \u4E2A\u63D0\u793A",
      "{{count}} prompts": "{{count}} \u4E2A\u63D0\u793A",
      "(from {{extensionName}})": "\uFF08\u6765\u81EA {{extensionName}}\uFF09",
      OAuth: "OAuth",
      "OAuth expired": "OAuth \u5DF2\u8FC7\u671F",
      "OAuth not authenticated": "OAuth \u672A\u8BA4\u8BC1",
      "tools and prompts will appear when ready": "\u5DE5\u5177\u548C\u63D0\u793A\u5C06\u5728\u5C31\u7EEA\u65F6\u663E\u793A",
      "{{count}} tools cached": "{{count}} \u4E2A\u5DE5\u5177\u5DF2\u7F13\u5B58",
      "Tools:": "\u5DE5\u5177\uFF1A",
      "Parameters:": "\u53C2\u6570\uFF1A",
      "Prompts:": "\u63D0\u793A\uFF1A",
      Blocked: "\u5DF2\u963B\u6B62",
      "\u{1F4A1} Tips:": "\u{1F4A1} \u63D0\u793A\uFF1A",
      Use: "\u4F7F\u7528",
      "to show server and tool descriptions": "\u663E\u793A\u670D\u52A1\u5668\u548C\u5DE5\u5177\u63CF\u8FF0",
      "to show tool parameter schemas": "\u663E\u793A\u5DE5\u5177\u53C2\u6570\u67B6\u6784",
      "to hide descriptions": "\u9690\u85CF\u63CF\u8FF0",
      "to authenticate with OAuth-enabled servers": "\u4F7F\u7528\u652F\u6301 OAuth \u7684\u670D\u52A1\u5668\u8FDB\u884C\u8BA4\u8BC1",
      Press: "\u6309",
      "to toggle tool descriptions on/off": "\u5207\u6362\u5DE5\u5177\u63CF\u8FF0\u5F00\u5173",
      "Starting OAuth authentication for MCP server '{{name}}'...": "\u6B63\u5728\u4E3A MCP \u670D\u52A1\u5668 '{{name}}' \u542F\u52A8 OAuth \u8BA4\u8BC1...",
      "Restarting MCP servers...": "\u6B63\u5728\u91CD\u542F MCP \u670D\u52A1\u5668...",
      // ============================================================================
      // Startup Tips
      // ============================================================================
      "Tips:": "\u63D0\u793A\uFF1A",
      "Use /compress when the conversation gets long to summarize history and free up context.": "\u5BF9\u8BDD\u53D8\u957F\u65F6\u7528 /compress\uFF0C\u603B\u7ED3\u5386\u53F2\u5E76\u91CA\u653E\u4E0A\u4E0B\u6587\u3002",
      "Start a fresh idea with /clear or /new; the previous session stays available in history.": "\u7528 /clear \u6216 /new \u5F00\u542F\u65B0\u601D\u8DEF\uFF1B\u4E4B\u524D\u7684\u4F1A\u8BDD\u4F1A\u4FDD\u7559\u5728\u5386\u53F2\u8BB0\u5F55\u4E2D\u3002",
      "Use /bug to submit issues to the maintainers when something goes off.": "\u9047\u5230\u95EE\u9898\u65F6\uFF0C\u7528 /bug \u5C06\u95EE\u9898\u63D0\u4EA4\u7ED9\u7EF4\u62A4\u8005\u3002",
      "Switch auth type quickly with /auth.": "\u7528 /auth \u5FEB\u901F\u5207\u6362\u8BA4\u8BC1\u65B9\u5F0F\u3002",
      "You can run any shell commands from Qwen Code using ! (e.g. !ls).": "\u5728 Qwen Code \u4E2D\u4F7F\u7528 ! \u53EF\u8FD0\u884C\u4EFB\u610F shell \u547D\u4EE4\uFF08\u4F8B\u5982 !ls\uFF09\u3002",
      "Type / to open the command popup; Tab autocompletes slash commands and saved prompts.": "\u8F93\u5165 / \u6253\u5F00\u547D\u4EE4\u5F39\u7A97\uFF1B\u6309 Tab \u81EA\u52A8\u8865\u5168\u659C\u6760\u547D\u4EE4\u548C\u4FDD\u5B58\u7684\u63D0\u793A\u8BCD\u3002",
      "You can resume a previous conversation by running qwen --continue or qwen --resume.": "\u8FD0\u884C qwen --continue \u6216 qwen --resume \u53EF\u7EE7\u7EED\u4E4B\u524D\u7684\u4F1A\u8BDD\u3002",
      "You can switch permission mode quickly with Shift+Tab or /approval-mode.": "\u6309 Shift+Tab \u6216\u8F93\u5165 /approval-mode \u53EF\u5FEB\u901F\u5207\u6362\u6743\u9650\u6A21\u5F0F\u3002",
      "You can switch permission mode quickly with Tab or /approval-mode.": "\u6309 Tab \u6216\u8F93\u5165 /approval-mode \u53EF\u5FEB\u901F\u5207\u6362\u6743\u9650\u6A21\u5F0F\u3002",
      "Try /insight to generate personalized insights from your chat history.": "\u8BD5\u8BD5 /insight\uFF0C\u4ECE\u804A\u5929\u8BB0\u5F55\u4E2D\u751F\u6210\u4E2A\u6027\u5316\u6D1E\u5BDF\u3002",
      // ============================================================================
      // Exit Screen / Stats
      // ============================================================================
