      "Agent Active:": "\u667A\u80FD\u4F53\u6D3B\u8DC3\u65F6\u95F4\uFF1A",
      "API Time:": "API \u65F6\u95F4\uFF1A",
      "Tool Time:": "\u5DE5\u5177\u65F6\u95F4\uFF1A",
